// ----------------------------- drawing -----------------------------

var showConstant = false;

function drawScreen(){	
	theShader.setUniform("u_resolution", [width, height]);
	theShader.setUniform("u_position", u_position);
	theShader.setUniform("u_dimension", u_dimension);
	theShader.setUniform("u_constant", u_constant);

	canvas.shader(theShader);
	canvas.rect(0,0,width,height);
	image(canvas,0,0);

	if (showConstant)
  	writeConstant();
}

function writeConstant(){
	fill(255);
	stroke(120);
	strokeWeight(3);
  rect(10,10,200,30);

	fill(0);
	noStroke();
	textSize(25);
	textAlign(CENTER,CENTER);
	text((u_constant[0]).toFixed(3)+"+"+(u_constant[1]).toFixed(3)+"*i",10+100,10+15);
}

// ----------------------------- drawing window update -----------------------------

function moveDrawingWindow(dx, dy){
	u_position[0] += dx;
	u_position[1] += dy;
	drawScreen();
}

function zoomToPoint(x, y, zoom){
	var t = 1/zoom;
	u_position = [u_position[0]*t+x*(1-t), u_position[1]*t+y*(1-t)];
	u_dimension = [u_dimension[0]*t, u_dimension[1]*t];		
	drawScreen();
}

function zoomToCenter(zoom){
	zoomToPoint(u_position[0]+u_dimension[0]/2, u_position[1]+u_dimension[1]/2, zoom);
}

