let vertShader = `

#ifdef GL_ES //for browser or mobile
//can change mediump to either lowp or highp.
precision mediump float;
#endif

// Input:
attribute vec3 aPosition;  //position of the vertex

void main() {
  vec4 positionVec4 = vec4(aPosition, 1.0);

	// This is a weird behaviour in p5. Need to scale the vertices so they will appear in the right place.
  positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

	//Output:
  gl_Position = positionVec4;
}`;


// === Tab: frag shader ===
const MAX_ITERATIONS = 64;
const RADIUS = 16;
const SCALE = 5;

let fragShader=`
#ifdef GL_ES 
precision mediump float;
#endif

uniform vec2 u_resolution;
uniform vec2 u_dimension;
uniform vec2 u_position;
uniform vec2 u_constant;

int f(float x, float y){
	float xx = 0.0;
	float yy = 0.0;
	for(int k=0;k<${MAX_ITERATIONS};k++){
		if (x*x+y*y>float(${RADIUS})){
			return k;
		}
		xx = x*x-y*y-u_constant[0];
		yy = 2.0*x*y-u_constant[1];
		x = xx;
		y = yy;
	}
	return -1;
}

vec3 hsb2rgb(in vec3 c){
    vec3 rgb = clamp(abs(mod(c.x*6.0+vec3(0.0,4.0,2.0),
                             6.0)-3.0)-1.0,
                     0.0,
                     1.0 );
    rgb = rgb*rgb*(3.0-2.0*rgb);
    return c.z * mix( vec3(1.0), rgb, c.y);
}

void main() {
		//get position in the complex plane.
		vec2 normalizePos = gl_FragCoord.xy/u_resolution.xy;
		normalizePos/=2.0;
		normalizePos.y = 1.0-normalizePos.y;
		normalizePos = u_dimension*normalizePos+u_position; 

		// number of iterations to get outside of ${RADIUS}.
		int iterations = f(normalizePos.x, normalizePos.y);
		if (iterations<0){
			//didn't get outside of ${RADIUS} - use black.
			gl_FragColor = vec4(0.0,0.0,0.0,1.0);
			return;
		}
    vec3 hsbColor = vec3(float(iterations)/float(${MAX_ITERATIONS}),1.0,1.0);
    gl_FragColor = vec4(hsb2rgb(hsbColor), 1.0);

}


`;

